func (q *Queries) ListHeldResourceIDs(ctx context.Context, arg ListHeldResourceIDsParams) ([]string, error) {
	rows, err := q.db.Query(ctx, listHeldResourceIDs, arg.TenantID, arg.ResourceType)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var resource_id string
		if err := rows.Scan(&resource_id); err != nil {
			return nil, err
		}
		items = append(items, resource_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

